const BOARD_CHECK_TRIGGER="trig_018M56cpoEonkTY9bDHLU6gR";
const SR=window.SpeechRecognition||window.webkitSpeechRecognition;
let mcp=null, convo=[], busy=false, listening=false, rec=null, ctrl=null, micBlocked=false;
const voiceCards=new Set(), spoken=new Set();
const hint=t=>{const a=$("#answer");a.hidden=!t;a.textContent=t||""};
const clip=x=>{let s=typeof x==="string"?x:JSON.stringify(x);return s&&s.length>7000?s.slice(0,7000)+" …(cut)":(s||"(empty)")};
/* v30: claude.ai artifact frames don't grant the microphone (iframe allow list has no "microphone", checked 2026-10-21), so in-board speech recognition can't hear anything. Use it only if the frame ever allows the mic; otherwise Tap to talk opens the keyboard (use its mic). */
const MIC_OK=(()=>{try{const p=document.permissionsPolicy||document.featurePolicy;return !!(p&&p.allowsFeature&&p.allowsFeature("microphone"))}catch(e){return false}})();
if(SR&&MIC_OK){$("#handsWrap").hidden=false}
function setTalk(){const b=$("#talkBtn");b.classList.toggle("on",listening);b.textContent=listening?"Listening… tap to stop":(busy?"Thinking…":"Tap to talk")}
function renderConvo(){const el=$("#convo");el.hidden=!convo.length;el.innerHTML=convo.map(m=>`<div class="msg ${m.role==="assistant"?"claude":""}"><span class="who">${m.role==="assistant"?"Claude":"You"}</span>${esc(m.content)}</div>`).join("");el.scrollTop=el.scrollHeight}
function speak(t,after){
  if(!$("#speakOn").checked||!window.speechSynthesis){after&&after();return}
  try{speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(String(t).replace(/[*#_`>|]/g," "));u.lang="en-CA";u.rate=1.05;u.onend=()=>after&&after();u.onerror=()=>after&&after();speechSynthesis.speak(u)}catch(e){after&&after()}
}
/* v29 (Calvin 2026-10-21): the Claude phone app view can expose speech recognition that never starts, which left the button stuck on "Listening". Now: a 2.5 s start watchdog, a 25 s hard stop, tap-to-stop always works, and if the mic can't start the board falls back to the phone keyboard mic (remembered on this device). */
let recTimer=null, recCap=null;
try{if(localStorage.getItem("hs_mic_blocked")==="1")micBlocked=true}catch(e){}
function endListen(send){
  clearTimeout(recTimer);clearTimeout(recCap);recTimer=recCap=null;
  const r=rec;rec=null;
  if(r){r.onstart=r.onaudiostart=r.onresult=r.onerror=r.onend=null;try{r.abort()}catch(e){}}
  listening=false;setTalk();
  const t=$("#ask").value.trim();if(send&&t)ask(t);
}
function micFallback(msg){
  micBlocked=true;try{localStorage.setItem("hs_mic_blocked","1")}catch(e){}
  $("#handsWrap").hidden=true;endListen(false);
  const a=$("#ask");a.focus();try{a.scrollIntoView({block:"center"})}catch(e){}
  hint(msg||"Voice can't start in this view. Tap the mic on your phone keyboard, talk, then tap Send.");
}
function listen(){
  if(listening){endListen(true);return}
  if(!SR||!MIC_OK||micBlocked){micFallback("Tap the mic on your keyboard, talk, then tap Send. (The Claude app doesn't let boards use the mic directly. For hands-free while driving, use voice mode in a regular Claude chat.)");return}
  try{window.speechSynthesis&&speechSynthesis.cancel()}catch(e){}
  hint("");let started=false,heard=false,r;
  try{r=new SR()}catch(e){micFallback();return}
  rec=r;r.lang="en-CA";r.interimResults=true;r.continuous=false;
  r.onstart=r.onaudiostart=()=>{started=true};
  r.onresult=e=>{started=true;let t="";for(const x of e.results)t+=x[0].transcript;$("#ask").value=t;heard=true};
  r.onerror=e=>{const c=e&&e.error;
    if(c==="not-allowed"||c==="service-not-allowed"||c==="audio-capture"||c==="network"){micFallback();return}
    if(c==="no-speech"){endListen(false);hint("Didn't catch that. Tap and try again, or use the mic on your keyboard.");return}
    endListen(heard)};
  r.onend=()=>{if(rec===r)endListen(heard)};
  try{r.start();listening=true;setTalk()}catch(e){micFallback();return}
  recTimer=setTimeout(()=>{if(rec===r&&!started)micFallback()},2500);
  recCap=setTimeout(()=>{if(rec===r)endListen(heard)},25000);
}
async function call(server,tool,input,signal){
  if(!mcp)throw new Error("Connectors aren't available in this view of the board.");
  try{const r=await mcp.callTool(server,tool,input,{signal});const tx=(r.content||[]).filter(b=>b.type==="text").map(b=>b.text);return clip(r.structuredContent??(tx.length>1?tx.join("\n"):(r.payload??tx[0])))}
  catch(e){const c=e&&e.code;const m={needs_reauth:`${server} needs reconnecting in claude.ai Settings, Connectors.`,server_not_connected:`${server} isn't connected.`,not_in_manifest:`${server} is turned off for this board.`,approval_required:`${server} needs Calvin's approval on the board first.`,blocked_by_policy:`${server} is blocked by policy.`}[c];throw new Error(m||`${server} lookup failed (${c||"error"}).`)}
}
