// v0.22 (Calvin 2026-11-10): personal view settings - lane order, hide Today / Talk, lane that opens first, theme + accent colour. Saved per person in board/view; only your own board, only your own view.
const LANE_NAMES=Object.fromEntries(LANES.map(l=>[l[0],l[1]]));let VIEW={};let firstView=true;
const ownBoard=!opts.owner||!opts.me||opts.owner===opts.me.id;
function applyView(v){VIEW=v||{};
  if(Array.isArray(VIEW.laneOrder)){const ord=VIEW.laneOrder.filter(k=>LANE_NAMES[k]);LANES.sort((a,b)=>{const ia=ord.indexOf(a[0]),ib=ord.indexOf(b[0]);return (ia<0?99:ia)-(ib<0?99:ib)});}
  const td=R.querySelector('section[aria-labelledby="todayH"]'),tk=R.querySelector('section[aria-labelledby="askH"]'),tp=R.querySelector('#pane-board > .top');
  if(td)td.hidden=!!VIEW.hideToday;if(tk)tk.hidden=!!VIEW.hideTalk;if(tp)tp.hidden=!!(VIEW.hideToday&&VIEW.hideTalk);
  if(firstView&&VIEW.defaultLane&&LANE_NAMES[VIEW.defaultLane]){active=VIEW.defaultLane}firstView=false;
  if(ownBoard&&opts.onTheme)opts.onTheme(VIEW);
  render();}
